// Generated by Cypress Author on 2026-11-02.
const displays = [
  { name: 'desktop', width: 1440, height: 1000 },
  { name: 'mobile', width: 390, height: 844 },
];
const orders = [
  ['service', 'barber', 'date'], ['service', 'date', 'barber'],
  ['barber', 'service', 'date'], ['barber', 'date', 'service'],
  ['date', 'service', 'barber'], ['date', 'barber', 'service'],
];

function details(seed, lang = 'en', time = '09:00') {
  cy.visit(`/book/?lang=${lang}&service=${seed.services.cut}&barber=${seed.barbers.alan}&date=${seed.date}&time=${time}`);
  cy.get('#details').should('be.visible');
}

function assertFitsViewport() {
  cy.document().then((doc) => {
    expect(doc.documentElement.scrollWidth, 'page has no horizontal overflow').to.be.at.most(doc.documentElement.clientWidth + 1);
  });
}

for (const lang of ['bg', 'en']) {
  for (const display of displays) {
    describe(`Public booking / ${lang} / ${display.name}`, () => {
      beforeEach(() => cy.viewport(display.width, display.height));

      it('home navigation and language actions → correct destinations without business changes', () => {
        cy.task('db:snapshot').then((before) => {
          cy.visit(`/?lang=${lang}`);
          cy.get('html').should('have.attr', 'lang', lang);
          assertFitsViewport();
          cy.screenshot(`home-${lang}-${display.name}`, { capture: 'viewport' });
          cy.get('a[href="#main"]').focus().click();
          cy.location('hash').should('eq', '#main');
          cy.get('a[href="/"]').click();
          cy.location('pathname').should('eq', '/');
          for (const section of ['services', 'gallery', 'reviews', 'contact']) {
            cy.get(`a[href="#${section}"]`).first().click();
            cy.location('hash').should('eq', `#${section}`);
            cy.get(`#${section}`).should('be.visible');
          }
          cy.get('a[href^="tel:"]').should('have.attr', 'href', 'tel:+359889771917');
          cy.get('a[href^="https://www.google.com/maps/"]').should('have.attr', 'href').and('include', 'Alan+Barberhouse');
          cy.get('a[lang]').filter(`[lang="${lang === 'bg' ? 'en' : 'bg'}"]`).click();
          cy.get('html').should('have.attr', 'lang', lang === 'bg' ? 'en' : 'bg');
          cy.get('a[lang]').filter(`[lang="${lang}"]`).click();
          // All three book CTAs must target the same real booking route.
          cy.get('a[href="/book/"]').should('have.length', 3).each(($link) => {
            expect($link.text().trim()).not.to.equal('');
          });
          const visibleCtas = display.name === 'mobile' ? 2 : 3;
          for (let index = 0; index < visibleCtas; index += 1) {
            cy.get('a[href="/book/"]:visible').eq(index).click();
            cy.location('pathname').should('eq', '/book/');
            cy.get('a[href="/"]').click();
            cy.location('pathname').should('eq', '/');
          }
          cy.get('a[href="/book/"]:visible').first().click();
          cy.location('pathname').should('eq', '/book/');
          cy.get('a[href="#main"]').focus().click();
          cy.location('hash').should('eq', '#main');
          cy.get('a[href="/staff/login/"]').click();
          cy.get('#id_username').should('be.visible');
          cy.get('a[href="/"]').click();
          cy.location('pathname').should('eq', '/');
          cy.assertNoBusinessChange(before);
        });
      });

      for (const order of orders) {
        it(`choose ${order.join(' → ')} → matching times, clear/apply/reset with no database writes`, () => {
          cy.get('@seed').then((seed) => {
            cy.task('db:snapshot').then((before) => {
              cy.visit(`/book/?lang=${lang}`);
              const values = { service: seed.services.cut, barber: seed.barbers.alan, date: seed.date };
              for (const field of order) cy.chooseFilter(field, values[field]);
              cy.get('[data-booking-time]').should('have.length.greaterThan', 0);
              cy.get('[data-booking-time]').contains('12:00').should('not.exist');
              cy.get('#time-selection-heading').should('be.focused');
              assertFitsViewport();
              cy.intercept('GET', '/book/?*').as('apply');
              cy.get('#visit-selection button[type!="button"]').click();
              cy.wait('@apply');
              for (const field of order) {
                cy.get(`[data-clear-filter="${field}"]`).click();
                cy.wait('@apply');
                cy.get(`#visit-selection [name="${field}"]`).should('have.value', '');
              }
              cy.get('[data-reset-filters]').click();
              cy.wait('@apply');
              cy.get('#visit-selection select').each(($select) => expect($select.val()).to.equal(''));
              cy.get('[data-booking-time]').should('not.exist');
              cy.assertNoBusinessChange(before);
            });
          });
        });
      }

      it('confirm valid phone then cancel → exactly one appointment and one cancellation', () => {
        cy.get('@seed').then((seed) => {
          cy.visit(`/book/?lang=${lang}`);
          cy.chooseFilter('service', seed.services.cut);
          cy.chooseFilter('barber', seed.barbers.alan);
          cy.chooseFilter('date', seed.date);
          cy.waitForScroll();
          cy.assertGuidedStep('#time-selection-heading');
          cy.get('#time-selection-heading').should('be.focused').should(($heading) => {
            const rect = $heading[0].getBoundingClientRect();
            expect(rect.top).to.be.at.least(0);
            expect(rect.bottom).to.be.at.most(display.height);
          });
          cy.window().then((win) => {
            const rect = win.document.querySelector('#time-selection-heading').getBoundingClientRect();
            cy.writeFile(`.artifacts/cypress/scroll-${lang}-${display.name}.json`, {
              scrollY: win.scrollY, top: rect.top, bottom: rect.bottom, viewportHeight: win.innerHeight,
              focused: win.document.activeElement.id,
            });
          });
          cy.screenshot(`times-${lang}-${display.name}`, { capture: 'viewport' });
          cy.intercept('GET', '/book/?*').as('details');
          cy.get('[data-booking-time]').contains('09:00').click();
          cy.wait('@details');
          cy.waitForScroll();
          cy.assertGuidedStep('#details-heading');
          cy.get('#details-heading').should('be.focused').should(($heading) => {
            const rect = $heading[0].getBoundingClientRect();
            expect(rect.top).to.be.at.least(0);
            expect(rect.bottom).to.be.at.most(display.height);
          });
          cy.screenshot(`details-step-${lang}-${display.name}`, { capture: 'viewport' });
          cy.get('#details [name="customer_name"]').type('Synthetic Browser Client');
          cy.get('#details [name="phone"]').type(display.name === 'mobile' ? '+359888123456' : '0888123456');
          cy.get('#details [name="email"]').type('browser@example.invalid');
          assertFitsViewport();
          cy.screenshot(`details-${lang}-${display.name}`, { capture: 'viewport' });
          cy.get('#details button').click();
          cy.location('pathname').should('match', /^\/book\/[a-f0-9-]+\/$/);
          cy.contains('Synthetic Browser Client').should('be.visible');
          cy.task('db:snapshot').then((after) => {
            expect(after.appointments).to.have.length(3);
            const created = after.appointments.find((row) => row.customer_name === 'Synthetic Browser Client');
            expect(created).to.include({ phone: display.name === 'mobile' ? '+359888123456' : '0888123456', price: '20.00', duration_minutes: 30, cancelled_at: null });
            expect(created.barber_id).to.equal(seed.barbers.alan);
            expect(created.service_id).to.equal(seed.services.cut);
            cy.reload();
            cy.assertNoBusinessChange(after);
            cy.get('form[action$="/cancel/"] button').click();
            cy.get('form[action$="/cancel/"]').should('not.exist');
            cy.task('db:snapshot').then((cancelled) => {
              expect(cancelled.appointments).to.have.length(3);
              const row = cancelled.appointments.find((item) => item.id === created.id);
              expect(row.cancelled_at).to.be.a('string');
              expect({ ...row, cancelled_at: null }).to.deep.equal(created);
              for (const key of Object.keys(after).filter((key) => key !== 'appointments')) {
                expect(cancelled[key], key).to.deep.equal(after[key]);
              }
              cy.get('main a[href="/book/"]').click();
              cy.location('pathname').should('eq', '/book/');
              cy.assertNoBusinessChange(cancelled);
            });
          });
        });
      });
    });
  }
}

describe('Public booking validation and recovery', () => {
  it('required and invalid phone submissions → visible errors and no appointments', () => {
    cy.get('@seed').then((seed) => {
      details(seed);
      cy.task('db:snapshot').then((before) => {
        cy.get('#details [name="customer_name"]').type('Synthetic Invalid');
        cy.get('#details button').click();
        cy.get('#details [name="phone"]').then(($field) => expect($field[0].validity.valueMissing).to.equal(true));
        for (const phone of ['', '123', '0888 123456', '+35988812345', '+3598881234567', '+44999111222', '088812345x', '０８８８１２３４５６']) {
          cy.get('#details [name="phone"]').clear();
          if (phone) cy.get('#details [name="phone"]').type(phone);
          // Submit the form directly to exercise server validation beyond HTML constraints.
          cy.get('#details form').submit();
          cy.get('#id_phone_error').should('be.visible').and('contain', 'exactly 9 digits')
            .and('contain', '0888123456').and('contain', '+359888123456');
          cy.assertNoBusinessChange(before);
        }
        cy.get('#details [name="phone"]').clear().type('0888123456');
        cy.get('#details [name="customer_name"]').clear().type('A');
        cy.get('#details form').submit();
        cy.get('#id_customer_name_error').should('be.visible').and('contain', 'at least 2 characters');
        cy.assertNoBusinessChange(before);
        cy.get('#details [name="customer_name"]').clear().type('Synthetic Invalid');
        cy.get('#details [name="email"]').type('invalid-email');
        cy.get('#details form').submit();
        cy.get('#id_email_error').should('be.visible').and('contain', 'valid email address');
        cy.assertNoBusinessChange(before);
      });
    });
  });

  it('compatibility, days off and stale filters → unavailable choices and recoverable empty state', () => {
    cy.get('@seed').then((seed) => {
      cy.task('db:snapshot').then((before) => {
        cy.visit('/book/?lang=en');
        cy.get(`#id_service option[value="${seed.services.inactive}"]`).should('not.exist');
        cy.get(`#id_barber option[value="${seed.barbers.inactive}"]`).should('not.exist');
        cy.chooseFilter('service', seed.services.beard);
        cy.get(`#id_barber option[value="${seed.barbers.boris}"]`).should('not.exist');
        cy.visit(`/book/?lang=en&barber=${seed.barbers.boris}&date=${seed.nextDate}`);
        cy.contains('No bookable times match these filters.').should('be.visible');
        cy.get('[data-booking-time]').should('not.exist');
        cy.get('#id_date').should('have.value', seed.nextDate);
        cy.get(`[data-date="${seed.nextDate}"]`).should('have.attr', 'aria-disabled', 'true');
        cy.get('[data-reset-filters]').click();
        cy.get('#id_barber').should('have.value', '');
        cy.visit(`/book/?lang=en&service=999999&barber=${seed.barbers.alan}&date=${seed.date}`);
        cy.get('#id_service').should('have.value', '999999');
        cy.get('[data-clear-filter="service"]').click();
        cy.get('#id_service').should('have.value', '');
        cy.assertNoBusinessChange(before);
      });
    });
  });

  it('calendar keyboard and month controls → constrained dates without database writes', () => {
    cy.task('db:snapshot').then((before) => {
      cy.visit('/book/?lang=en');
      cy.get('[data-month-step="-1"]').should('be.disabled');
      cy.get('#date-calendar [aria-current="date"]').focus().trigger('keydown', { key: 'ArrowRight' });
      cy.focused().should('have.attr', 'data-date');
      for (const key of ['ArrowDown', 'ArrowUp', 'ArrowLeft', 'Home', 'End', 'PageDown', 'PageUp']) {
        cy.focused().trigger('keydown', { key });
        cy.focused().should('have.attr', 'data-date');
        cy.focused().should('not.be.disabled');
      }
      cy.get('[data-month-step="1"]').should('not.be.disabled').click();
      cy.get('[data-month-step="1"]').should('be.disabled');
      cy.get('[data-month-step="-1"]').should('not.be.disabled').click();
      cy.get('[data-month-step="-1"]').should('be.disabled');
      cy.get('#date-calendar [disabled][data-date]').should('have.length.greaterThan', 0);
      cy.assertNoBusinessChange(before);
    });
  });

  it('failed availability refresh and retry → old times cleared and customer draft restored', () => {
    cy.get('@seed').then((seed) => {
      details(seed);
      cy.get('#details [name="customer_name"]').type('Synthetic Preserved');
      cy.get('#details [name="phone"]').type('0888123456');
      cy.task('db:snapshot').then((before) => {
        cy.intercept({ method: 'GET', url: '/book/?*', times: 1 }, { statusCode: 503, body: 'Synthetic outage' }).as('outage');
        cy.get('[data-booking-time]').contains('09:30').click();
        cy.wait('@outage');
        cy.get('[data-booking-retry]').should('be.visible');
        cy.get('#details').should('not.exist');
        cy.get('[data-booking-time]').should('not.exist');
        cy.intercept('GET', '/book/?*').as('retry');
        cy.get('[data-booking-retry]').click();
        cy.wait('@retry');
        cy.get('#details [name="customer_name"]').should('have.value', 'Synthetic Preserved');
        cy.get('#details [name="phone"]').should('have.value', '0888123456');
        cy.get('#details [name="time"]').should('have.value', '09:30');
        cy.assertNoBusinessChange(before);
      });
    });
  });

  it('rapid filter changes and history → newest intent wins, no database writes', () => {
    cy.get('@seed').then((seed) => {
      cy.visit('/book/?lang=en');
      cy.task('db:snapshot').then((before) => {
        cy.intercept('GET', '/book/?*', (req) => req.continue((res) => res.setDelay(150))).as('slowRefresh');
        cy.get('#id_service').select(String(seed.services.cut));
        cy.get('#id_service').select(String(seed.services.beard));
        cy.get('#id_service').should('have.value', String(seed.services.beard));
        cy.get('#booking-refresh [role="status"]').should('contain', 'Available options updated.');
        cy.get(`#id_barber option[value="${seed.barbers.boris}"]`).should('not.exist');
        cy.chooseFilter('barber', seed.barbers.alan);
        cy.go('back');
        cy.get('#id_barber').should('have.value', '');
        cy.go('forward');
        cy.get('#id_barber').should('have.value', String(seed.barbers.alan));
        cy.assertNoBusinessChange(before);
      });
    });
  });

  it('replay, foreign confirmation, missing CSRF and fabricated request IDs → protected database', () => {
    cy.get('@seed').then((seed) => {
      details(seed);
      cy.get('#details [name="customer_name"]').type('Synthetic Replay');
      cy.get('#details [name="phone"]').type('0888123456');
      cy.get('#details form').then(($form) => {
        const body = Object.fromEntries(new FormData($form[0]));
        cy.get('#details button').click();
        cy.location('pathname').should('match', /^\/book\/[a-f0-9-]+\/$/);
        cy.task('db:snapshot').then((before) => {
          cy.request({ method: 'POST', url: '/book/?lang=en', form: true, body }).its('status').should('eq', 200);
          cy.assertNoBusinessChange(before);
          cy.request({ url: `/book/${seed.appointments.boris.reference}/`, failOnStatusCode: false }).its('status').should('eq', 404);
          cy.request({ method: 'POST', url: '/book/', form: true, body: { ...body, csrfmiddlewaretoken: '' }, failOnStatusCode: false }).its('status').should('eq', 403);
          cy.request({ method: 'POST', url: '/book/', form: true, body: { ...body, request_id: '11111111-1111-4111-8111-111111111111' }, failOnStatusCode: false }).its('status').should('eq', 403);
          cy.assertNoBusinessChange(before);
        });
      });
    });
  });

  it('another customer takes the displayed time → visible rejection without duplicate appointment', () => {
    cy.get('@seed').then((seed) => {
      details(seed);
      cy.get('#details [name="customer_name"]').type('Synthetic Stale Slot');
      cy.get('#details [name="phone"]').type('0888123456');
      cy.task('db:occupySlot');
      cy.task('db:snapshot').then((occupied) => {
        cy.get('#details button').click();
        cy.location('pathname').should('eq', '/book/');
        cy.get('#details .errorlist').should('be.visible');
        cy.assertNoBusinessChange(occupied);
      });
    });
  });

  for (const lang of ['en', 'bg']) {
    it(`unenhanced ${lang} forms → apply filters and follow time links without inline JavaScript`, () => {
      cy.get('@seed').then((seed) => {
        cy.task('db:snapshot').then((before) => {
          // Remove only the app enhancement script from each real page response;
          // this also works when its static file was previously HTTP-cached.
          cy.intercept({ method: 'GET', pathname: '/book/' }, (req) => req.continue((res) => {
            res.body = res.body.replace(/<script\b[^>]*src="[^"]*booking\/booking\.js"[^>]*>[\s\S]*?<\/script>/g, '');
          }));
          cy.visit(`/book/?lang=${lang}`);
          cy.get('script[src$="booking/booking.js"]').should('not.exist');
          cy.get('#id_date').should('be.visible');
          cy.get('#id_service').select(String(seed.services.cut));
          cy.get('#id_barber').select(String(seed.barbers.alan));
          cy.get('#id_date').select(seed.date);
          cy.get('#visit-selection button[type!="button"]').click();
          cy.get('[data-booking-time]').contains('09:00').click();
          cy.get('#details').should('be.visible');
          cy.assertNoBusinessChange(before);
        });
      });
    });
  }
});
